slide("STATEMENT", "Idea",
  [w("It "), hi("learns"), w(" its strategy")],
  "19 strategies · 239 games · 10 cases",
  "spec/lab.py plays strategy variants (anchor depth, concession pace, closing rules, term order) on practice cases and records every game. The agent picks the best proven strategy per case from learned_playbook.json, with safety rules: a variant only replaces base if it gains and loses no case by more than 0.05.");

pres.addSection({ title: "Proof" });
slide("STAT", "Proof",
  [hi("88/88")],
  "replays reproduced exactly",
  "spec/replay.py replays games against recorded ones: suppliers answer identical e-mails identically, so only diverging games need a live practice session. Experiments become nearly free.");

slide("STAT", "Proof",
  [w("0.665 → "), hi("0.716")],
  "average deal score",
  "Code-only: base strategy 0.665, learned picks 0.716, leave-one-out (picks tested on unseen cases) 0.682. Case wins: P02 0.507, P08 0.593, P18 0.513, P01 0.859.");

slide("STAT", "Proof",
  [hi("204")],
  "tests passing",
  "204 passed, 1 skipped (opt-in hosted smoke test). Ruff clean.");

pres.addSection({ title: "Close" });
slide("STATEMENT", "Close",
  [br("Better deals,"), hi("every game.")],
  null,
  "Each negotiation adds to the experiment log and sharpens the playbook. Next: more cases and model-mode sweeps.");

(async () => {
  await pres.writeFile({ fileName: OUT });
  await applyTheme(OUT, THEME);
  console.log("wrote", OUT);
})();
EOF
